window.VD=window.VD||{};window.VD["skoda/roomster-5j"]={"roomster-5j-activate-comfort-turn-signals":"<p><strong>Function:</strong> Activates the convenience turn signals.  </p>\n<p><em>(By default, the number of flashes is 3. You can change this value to any number between 1 and 5.) </em>)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em>Byte<strong> 12: </strong></em><br/><em>Bit <strong>5</strong>: Check <strong>“Comfort Turn Signals active</strong> ”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-011f47aa.webp\"/></figure>","roomster-5j-activate-coming-home-leaving-home":"<p><strong>Purpose: </strong> To activate Coming-Home / Leaving-Home.  </p>\n<p>(To work properly, the vehicle must be equipped with a light sensor. Headlight switch must be in “Auto” position.   <br/>Without the light sensor, it will be necessary to make a headlight call to activate the coming-home).  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>10 </strong>: <br/>Bit <strong>1</strong>: Check “Leaving-Home (LH) active”<br/>Bit <strong>2</strong>: Check “Coming-Home (CH) active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-polo-6r-cominghome-b8af74dc.webp\"/></figure>","roomster-5j-activate-daytime-running-lights-drl":"<p><strong>Purpose:</strong> to activate the daytime running lights (DRL).  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>23</strong>: </em><br/><em>Bit <strong>6 : </strong> Check Function “Daytime Running Light (DRL)” active</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte23-e94f1178.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>12 </strong>: </em><br/><em>Bit <strong>1</strong>: Tick “Daytime Running Light (DRL) adjustable (Manually AND/OR instrument Cluster)”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","roomster-5j-activate-driving-school-mode-rcd-210-rcd-310":"<p><strong>Purpose:</strong> Allows you to add a Driving School mode view to the RCD 210, RCD 310 that displays turn signals, speed … (Also ideal for accompanied driving) <br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“56 – Radio</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Channel 2</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“1</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/golf6_golf_vi_fahrschulfunktion-5b883ac1.webp\"/></figure>","roomster-5j-activate-interior-lighting-on-key-removal":"<p><strong>Purpose: </strong>to activate the interior lighting when the key is removed from the neiman.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>12</strong>:<br/>Bit<strong> 2</strong>: check “Interior Light after ignition Key removal active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","roomster-5j-activate-rain-sensor":"<p><strong>Purpose</strong>: to activate the rain sensor.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select,</p>\n<p><em>Byte <strong>14</strong>: </em> <br/><em>Bit <strong>1</strong>: Check “Rain Sensor Function active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte14-cd640f80.webp\"/></figure>\n<p><strong>Line 2: </strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select the “RLS” module and click on “Long Coding Helper”:</p>\n<p><em><em>Byte <strong>4</strong>: </em></em><br/><em><em>Bit <strong>5</strong>: Uncheck “Rain Sensor inactive”.</em></em></p>","roomster-5j-activate-wiper-change-mode":"<p><strong>Purpose</strong>: activates changeover mode for front wipers.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select,</p>\n<p><em>Byte <strong>14</strong>: </em><br/><em>Bit<strong> 2</strong>: Check “Service Position for Front Wiper active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte14-cd640f80.webp\"/></figure>\n<p><strong>Line 2: </strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Select <strong>Channel 23</strong>: <em>Set value to 1.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Adaptation_channel231-91e9521d.webp\"/></figure>","roomster-5j-adjusting-light-sensor-sensitivity":"<p><strong>Purpose: </strong>Adjusts the sensitivity of the light sensor.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>:  </em><br/><em>Bits <strong>3–4</strong>: Select from the drop-down list<br/>– 00 Normal light activation threshold<br/>– 08 Earlier light activation threshold (+20%)<br/>– 10 Light Activation Threshold earlier (+40%)<br/>– 08 Light Activation Threshold earlier (+60%)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","roomster-5j-automatic-closing-of-windows-and-roof-in-case-of-rain":"<p><strong>Purpose</strong>: Automatically closes windows and sunroof when it rains.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>6: </strong> Check “Rain closing active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4A6D5E39-CE5A-476F-995D-444CD637E3AD-af64c8a6.webp\"/></figure>\n<p><strong>Line 2 </strong>:</p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “RLS” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Rain closing active”.</em></p>","roomster-5j-automatic-door-locking":"<p><strong>Purpose: </strong>to set automatic door locking from 15km/h.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Auto-Lock (Automatic Locking above 15 km/h)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","roomster-5j-automatic-door-locking-after-30s":"<p><strong>Purpose: </strong>to set automatic door unlocking when the vehicle has been unlocked but no doors have been opened for 30 seconds.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>5</strong>: Uncheck “Central Locking Re-locking (after 30 seconds) active”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte4-6c468b48.webp\"/></figure>","roomster-5j-automatic-door-unlocking":"<p><strong>Purpose: </strong>to configure automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Auto-Unlock (Unlocking when Removing the Ignition Key)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","roomster-5j-automatic-headlamp-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong>: <br/>Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","roomster-5j-change-number-of-flashes-comfort-flashers":"<p><strong>Purpose:</strong> Allows you to change the number of flashes after activating the comfort turn signals.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p>5 – Select<strong> Channel 43</strong> (Lights: Comfort Turn Signals (Cycles) from the drop-down list)</p>\n<p><em>Select a value between 1 and 5</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Adaptation_channel43-3a96f44b.webp\"/></figure>","roomster-5j-change-odb-language":"<p><strong>Purpose:</strong> Select the language of your on-board computer.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Language Version</strong>”.<br/><br/><strong>6</strong> – Select language from second value list  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/886F4702-2DBC-4C30-8716-D4D05CCE1338-da4cd84c.webp\"/></figure>","roomster-5j-coming-leaving-home-with-fog-lamps":"<p><strong>Purpose: </strong>Enables fog lamps to be used for Coming Home and Leaving Home.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>13</strong>:<br/>Bit<strong> 6</strong>: Uncheck “Coming-Home (CH) / Leaving-Home (LH) Variant (0 = Fog Lights / 1 = Low Beam)”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte13-092427d2.webp\"/></figure>","roomster-5j-coming-leaving-home-with-headlights":"<p><strong>Purpose: Allows you </strong>to use xenon (or halogen) headlights for the Coming Home and Leaving Home functions.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>13</strong>: </em><br/><em>Bit <strong>6</strong>: Check “Coming-Home (CH) / Leaving-Home (LH) Variant (0 = Fog Lights / 1 = Low Beam)”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte13-092427d2.webp\"/></figure>","roomster-5j-corner-lights":"<p><strong>Purpose:</strong> Allows you to turn on the cornering lights along with the fog lights.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em><strong>Byte 12: </strong></em><br/><em>Bit <strong>6</strong>: Check <strong>“Turn/Cornering Lights</strong> installed/active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-011f47aa.webp\"/></figure>","roomster-5j-corner-lights-with-turn-signal":"<p><strong>Purpose:</strong> Enables the cornering lights to turn on along with the fog lights when the turn signal is activated.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em>Byte <strong>21: </strong></em><br/><em>Bit <strong>2</strong>: Check <strong>“Cornering/Turn Lights via Turn Signal active</strong> ”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte21-023ebd48.webp\"/></figure>","roomster-5j-deactivate-horn-without-ignition":"<p><strong>Purpose:</strong> to deactivate the horn when the ignition is off.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Coding – 07”</strong> then <strong>“Long Coding Helper”.</strong><br/><br/><strong>5</strong> – Select Byte <strong>17</strong>, Bit <strong>3</strong><br/><br/><strong>6</strong> – Check <strong>“Horn with” Terminal 15 OFF “inactive</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8B27B62E-B23B-4D69-A15C-C56C9A00FC14-c93db85d.webp\"/></figure>","roomster-5j-deactivate-rear-wiper-when-reversing":"<p><strong>Purpose:</strong> to deactivate the automatic engagement of the rear wiper when reversing.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears,</p>\n<p><em>Byte <strong>14 </strong>: </em><br/><em>Bit<strong> 3</strong>: Uncheck “Comfort Funtion for Rear Wiper active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte14-cd640f80.webp\"/></figure>","roomster-5j-delete-belt-alarm":"<p><strong>Purpose:</strong> To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>:<br/>Then uncheck Bit <strong>1: </strong>“<strong>Seatbelt warning active/installed</strong>”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","roomster-5j-delete-odb-error-led-license-plate-light":"<p><strong>Purpose:</strong> Eliminates the error on the ODB when replacing original license plate light bulbs with non-error LEDs.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .<br/><br/><strong>4 </strong>– Click on “<strong> Coding – 07 </strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em><strong>Byte 11 </strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “</em>Lamp diagnotics for Lisense Plate Light active<em>”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte11-e6e5cf22.webp\"/></figure>","roomster-5j-disable-bluetooth-connection-beep":"<p><strong>Purpose </strong>: Disables the beep when a device successfully connects to the car radio’s Bluetooth.  </p>\n<p><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“77 – Telephone</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation 10</strong>”.</p>\n<p><strong>5</strong> – Select “Bluetooth acknowledgement signal” from the value list</p>\n<p><strong>6 </strong>– Select <strong>“Off” </strong>from the second drop-down list</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7P6-035-730-C_Module77_Adaptation_Bluetooth_acknow-580a5d47.webp\"/></figure>","roomster-5j-disable-parking-aid-beep":"<p><strong>Purpose:</strong> to deactivate the beep when reverse gear is engaged or when parking assistance is activated manually.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “10-Parking<strong>Assistance.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p><strong>5</strong> – Select <em>“Parking Aid Activation Tone</em> ” from the drop-down list<strong>:</strong></p>\n<p><em>Select <strong>“Off” from </strong>the second drop-down list</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-919-475-B_Module10_Adaptation_Parking_aid_acti-4dbee393.webp\"/></figure>","roomster-5j-door-lock-unlock-confirmation-beep-horn":"<p><strong>Purpose: </strong>to set confirmation of door locking/unlocking with beep (alarm) or horn.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>5</strong>: </em><br/><em>Bit <strong>1</strong>: Tick “Acoustical Locking Confirmation (Horn) active”.</em><br/><em>Bit <strong>4</strong>: Tick “Acoustical Unlocking Confirmation (Horn) active”. </em><br/><em>Bit <strong>7</strong>: Tick “Anti-Theft-System Activation Acoustical Confirmation (Horn) active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte5-90daaa01.webp\"/></figure>","roomster-5j-door-lock-unlock-confirmation-turn-signals":"<p><strong>Purpose: </strong>Used to set up confirmation of door locking using the indicators.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>5</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Locking/Unlocking Optical Confirmation (Turn Signal) active”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte5-90daaa01.webp\"/></figure>","roomster-5j-enable-bluetooth-audio-a2dp":"<p><strong>Purpose </strong>: Enables Bluetooth audio (A2DP).  </p>\n<p>You can listen to music from your A2DP-compatible phone or mp3 player.  </p>\n<p><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“77 – Telephone</strong>”.</p>\n<p><strong>4</strong> – Click on<strong> “Coding – 07”</strong> then<strong> “Long Coding Helper”.</strong></p>\n<p><strong>5 </strong>– <em>Byte<strong> 4 </strong>: </em><br/><em>Bit <strong>0</strong>: Uncheck <strong>“Multimedia Function (Bluetooth Audio) inactive”.</strong></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/D836B768-D607-4E70-92E6-06200694DE00-4d4d00be.webp\"/></figure>","roomster-5j-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>12</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Emergency Flashing<em>(Turn Signals) active </em>” (to activate turn signals)</em><br/><em>Bit <strong>4</strong>: Tick “Emergency Brake Flashing (Brake Light) active” (to activate brake lights)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","roomster-5j-needle-check":"<p><strong>Purpose:</strong> activates needle sweep when the car is started. (Needle Sweep)   <br/></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>10-Adaptation</strong>” then in the window that appears, click on the drop-down menu to choose a channel and select the “<strong>Staging</strong>” channel, if unavailable select the “<strong>indicator_celebration</strong>” channel:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/checkg6-9456b738.webp\"/></figure>\n<p><strong>5</strong> – In the “<strong>New value</strong>” box, click on the drop-down menu and select “<strong>active</strong>”. Once this new value has been entered, click on “<strong>Save</strong>”:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/checkg62-c8918051.webp\"/></figure>","roomster-5j-parking-aid-beep-frequency-setting":"<p><strong>Purpose:</strong> Allows you to adjust the frequency of the rear beeps during parking assistance.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “10-Parking<strong>Assistance.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p><strong>5</strong> – Select <em>“Speaker frequency for rear parking aid</em> ” from the drop-down list<strong>:</strong></p>\n<p><em>Select</em>a frequency from <em>Stage 1</em> (Low) to <em>Stage 9</em> (High) from the second drop-down list</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0_Module10_Adaptation_speaker-frequency_for_rear-a3ec7081.webp\"/></figure>","roomster-5j-retrofit-heated-mirrors":"<p><strong>Purpose</strong>: to activate heated and heated mirrors.  </p>\n<p>The vehicle must be equipped with heated rearview mirror glass. Or for retrofit installation of heated mirrors   </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears,</p>\n<p><em>Byte <strong>14 </strong>: </em><br/><em>Bit<strong> 3</strong>: Tick “Mirror Heating ON while rear Window Heater ON”<br/>Bit <strong>7</strong>: Tick “Heated Outside Mirrors installed”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte15-1c45d71d.webp\"/></figure>","roomster-5j-selective-door-unlocking":"<p><strong>Purpose: Allows </strong>you to configure selective door unlocking. <br/></p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Selective Central Locking (Single Door Locking) active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","roomster-5j-tear-wiping":"<p><strong>Purpose:</strong> to activate the windshield wipers once more after using the windshield washer, in order to remove any remaining water from the windshield.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on <strong>“Coding – 07”</strong> then <strong>“Long Coding Helper”.</strong></p>\n<p><strong>5</strong> – Select byte <strong>14</strong>, <br/>Bit <strong>4</strong>, Check <strong>“Tear Wiping Active”</strong>.</p>"};
